(async () => {
  const E = window.__editor; await E.app.ready; await E.ready3d;
  const F = await import('/src/engine/level/LevelFormat.js');
  const C = await import('/src/engine/level/ObjectCatalog.js');
  // the stored script without its text-key tags (I18N.md §4.10: the editor shows and compares it so) and the lines that carry a tag
  const TK = await import('/src/engine/i18n/TextKeys.js');
  const lines = (v) => JSON.stringify(TK.stripScriptTags(v));
  const tagged = (v) => (Array.isArray(v) ? v : [v]).map((l, k) => (/ #line:[0-9A-F]{32}$/.test(l) ? k + 1 : 0)).filter(Boolean).join();
  const R = window.R = { E, F, C, TK, lines, tagged, fails: [], orig: F.serializeLevel(E.state.level), sp: { ...E.state.level.spawn } };
  R.ok = (c, m) => { if (!c) { R.fails.push(m); setTimeout(() => { throw new Error('ASSERT ' + m); }); } return !!c; };
  R.settle = async () => { await T.sleep(150); while (E.view3d?.busy) await T.sleep(100); await T.sleep(250); };
  R.obj = (id) => E.state.getObject(id);
  R.dlg = (cls) => document.querySelector(`.le-overlay:not(.is-closing) .le-dialog${cls}`);
  R.dialogs = () => [...document.querySelectorAll('.le-overlay:not(.is-closing) .le-dialog')].map((d) => d.querySelector('.le-dialog-title')?.textContent);
  R.pop = async () => { document.querySelector('.le-inspector .le-field.is-script .le-script-pop-btn').click(); await T.sleep(300); return R.dlg('.is-script-dialog')?.querySelector('textarea'); };
  R.type = (ta, v) => { ta.value = v; ta.dispatchEvent(new Event('input', { bubbles: true })); };
  E.state.setTool('select');
  E.state.setView({ layout: 'split', storyPreview: false, storyValues: '', hiddenTypes: [] });
  return JSON.stringify({ level: E.state.level.name, bytes: R.orig.length });
})()

